def hidden_rule_fn(state):
    s = list(state)
    n = len(s)

    def is_prime(k):
        if k < 2:
            return False
        if k == 2:
            return True
        if k % 2 == 0:
            return False
        i = 3
        while i * i <= k:
            if k % i == 0:
                return False
            i += 2
        return True

    if n < 2:
        # Insufficient context; training never showed this case.
        return s + [0]

    if is_prime(n):
        new_val = (s[-1] ^ s[-2]) % 7
    elif n % 2 == 0:
        new_val = (s[-1] + s[-2] + 3) % 7
    else:
        new_val = (2 * s[-2] + 1) % 7

    return s + [new_val]

